set statement_timeout='900s'; set work_mem='64MB';
\copy (with d as (select platform, product_id, written_at::date wday, count(*) c from reviews where written_at is not null group by 1,2,3), p as (select platform, product_id, sum(c) total, max(c) top, count(*) days, avg(c) mean from d group by 1,2) select d.platform, count(distinct d.product_id) filter (where p.total>=20) products20, round(avg((p.top::numeric/p.total>=0.3)::int) filter (where p.total>=20 and d.c=p.top)*100,1) top30_pct_approx, sum(d.c) filter (where d.c>=10 and d.c>=5*p.mean) burst_reviews, round(sum(d.c) filter (where d.c>=10 and d.c>=5*p.mean)*100.0/sum(d.c),2) burst_pct, count(*) filter (where d.c>=10 and d.c>=5*p.mean) burst_days from d join p using(platform, product_id) group by 1 order by 1) to stdout with csv header
